const r = await tools.exec_command({cmd:"python3 - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/paper.pdf')
print('pages',len(r.pages))
terms=re.compile(r'decod|motion energy|variance|accuracy|coefficient|ridge|10 consecutive|20 minutes|30 Hz|526|33 ?%|six mice|6 mice',re.I)
for i,p in enumerate(r.pages):
 t=(p.extract_text() or '').replace('\x00',' ')
 if terms.search(t):
  lines=t.splitlines()
  hits=[]
  for j,line in enumerate(lines):
   if terms.search(line): hits.extend(range(max(0,j-3),min(len(lines),j+4)))
  seen=[]
  for j in sorted(set(hits)):
   seen.append(lines[j])
  print(f'\n=== PAGE {i+1} ===')
  print('\n'.join(seen))
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":50000});
text(r.output);

